85		{
86			if (Name.Len() <= MaxLen)
87			{
88				return Name;
89			}
90			TArray<FString> Words;
91			Name.ParseIntoArrayWS(Words);
92			if (Words.Num() > 1)
93			{
94				FString Result;
95				for (int32 i = 0; i < Words.Num() - 1; ++i)
96				{
97					Result += Words[i].Left(1).ToUpper() + TEXT(".");
98				}
99				Result += Words.Last();
100				return Result.Left(MaxLen);
101			}
102			return Name.Left(MaxLen - 1) + TEXT(".");
103		}
