232	void AGBHUD::ShowMessage(const FString& Text, float Duration)
233	{
234		if (Text.IsEmpty())
235		{
236			return;
237		}
238		const double EndTime = GetRealTime() + FMath::Max(0.1f, Duration);
239		for (FToast& Toast : Toasts)
240		{
241			if (Toast.Text == Text)
242			{
243				Toast.EndTime = EndTime;
244				return;
245			}
246		}
247		FToast Toast;
248		Toast.Text = Text;
249		Toast.EndTime = EndTime;
250		Toasts.Add(Toast);
251		while (Toasts.Num() > GBHudLayout::MaxToasts)
252		{
253			Toasts.RemoveAt(0);
254		}
255	}
