259	void AGBHUD::BindToPlayer(AGBPlayerCharacter* Player)
260	{
261		if (BoundPlayer.Get() == Player)
262		{
263			return;
264		}
265		if (AGBPlayerCharacter* Old = BoundPlayer.Get())
266		{
267			if (UGBAttributeComponent* Attributes = Old->GetAttributes())
268			{
269				Attributes->OnDamaged.Remove(DamagedHandle);
270			}
271			if (UGBSpellbookComponent* Spellbook = Old->GetSpellbook())
272			{
273				Spellbook->OnCastFailed.Remove(CastFailedHandle);
274				Spellbook->OnSpellCast.Remove(SpellCastHandle);
275			}
276		}
277		DamagedHandle.Reset();
278		CastFailedHandle.Reset();
279		SpellCastHandle.Reset();
280		BoundPlayer = Player;
281		if (!Player)
282		{
283			return;
284		}
285		if (UGBAttributeComponent* Attributes = Player->GetAttributes())
286		{
287			DamagedHandle = Attributes->OnDamaged.AddUObject(this, &AGBHUD::HandleDamaged);
288		}
289		if (UGBSpellbookComponent* Spellbook = Player->GetSpellbook())
290		{
291			CastFailedHandle = Spellbook->OnCastFailed.AddUObject(this, &AGBHUD::HandleCastFailed);
292			SpellCastHandle = Spellbook->OnSpellCast.AddUObject(this, &AGBHUD::HandleSpellCast);
293		}
