309	void AGBHUD::HandleCastFailed(FName SpellId, EGBCastFailReason Reason)
310	{
311		FString Text;
312		switch (Reason)
313		{
314		case EGBCastFailReason::NotEnoughMana: Text = TEXT("Not enough mana"); break;
315		case EGBCastFailReason::OnCooldown: Text = TEXT("On cooldown"); break;
316		case EGBCastFailReason::QTEFailed: Text = TEXT("Spell fizzled"); break;
317		case EGBCastFailReason::EmptySlot: Text = TEXT("No spell in that slot"); break;
318		case EGBCastFailReason::NotKnown: Text = TEXT("You have not learned that spell"); break;
319		case EGBCastFailReason::WrongHeldItem:
320		{
321			const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
322			const FGBSpellDefinition* Def = Data ? Data->FindSpell(SpellId) : nullptr;
323			Text = (Def && Def->bRequiresGun) ? TEXT("Need a gun in hand") : TEXT("Need the staff in hand");
324			break;
325		}
326		default:
327			break;
328		}
329		ShowMessage(Text, 1.2f);
330	}
