377	void AGBHUD::DrawOutline(float X, float Y, float W, float H, const FLinearColor& Color, float Thickness)
378	{
379		const float T = FMath::Max(1.f, Thickness);
380		DrawRect(Color, X, Y, W, T);
381		DrawRect(Color, X, Y + H - T, W, T);
