386	void AGBHUD::DrawPanel(const FGBHudSkinStyle& Style, float X, float Y, float W, float H)
387	{
388		const float S = UIScale();
389		if (Style.bChunky)
390		{
391			// 90s RPG: thick dark frame, parchment fill, a light bevel line on top.
392			const float B = FMath::Max(2.f, 4.f * S);
393			DrawRect(Style.Border, X, Y, W, H);
394			DrawRect(Style.Panel, X + B, Y + B, W - 2.f * B, H - 2.f * B);
395			DrawRect(FLinearColor(1.f, 1.f, 1.f, 0.2f), X + B, Y + B, W - 2.f * B, FMath::Max(1.f, 2.f * S));
396			DrawRect(FLinearColor(0.f, 0.f, 0.f, 0.25f), X + B, Y + H - B - FMath::Max(1.f, 2.f * S), W - 2.f * B, FMath::Max(1.f, 2.f * S));
397		}
398		else
399		{
400			// Cyberpunk: translucent fill, thin neon top line, a short side tick and a magenta corner.
401			const float T = FMath::Max(1.f, 1.5f * S);
402			DrawRect(Style.Panel, X, Y, W, H);
403			DrawRect(Style.Border, X, Y, W, T);
404			DrawRect(Style.Border, X, Y, T, H * 0.4f);
405			DrawRect(Style.Accent, X + W - 24.f * S, Y + H - 2.f * T, 24.f * S, 2.f * T);
406		}
407	}
