409	void AGBHUD::DrawBar(const FGBHudSkinStyle& Style, float X, float Y, float W, float H, float Fraction, const FLinearColor& Fill, const FString& Label)
410	{
411		const float S = UIScale();
412		DrawRect(GBHudLocal::Dark, X, Y, W, H);
413		DrawRect(Fill, X, Y, W * FMath::Clamp(Fraction, 0.f, 1.f), H);
414		if (Style.bChunky)
415		{
416			DrawOutline(X, Y, W, H, Style.Border, 2.f * S);
417		}
418		else
419		{
420			DrawRect(Style.Border, X, Y + H - FMath::Max(1.f, S), W, FMath::Max(1.f, S));
421		}
422		if (!Label.IsEmpty())
423		{
424			const float SizePx = FMath::Clamp(H / S * 0.8f, 10.f, 22.f);
425			const FVector2D Size = MeasureLabel(Label, SizePx);
426			DrawLabel(Label, GBHudLocal::White, X + W * 0.5f, Y + (H - Size.Y) * 0.5f, SizePx, 0.5f);
