442	
443	void AGBHUD::DrawHUD()
444	{
445		Super::DrawHUD();
446		if (!Canvas || Canvas->ClipX <= 0.f || Canvas->ClipY <= 0.f)
447		{
448			return;
449		}
450	
451		// Drop expired toasts here, once per frame.
452		const double Now = GetRealTime();
453		Toasts.RemoveAll([Now](const FToast& Toast) { return Toast.EndTime <= Now; });
454	
455		AGBPlayerCharacter* Player = GetPlayer();
456		BindToPlayer(Player);
457		const FGBHudSkinStyle& Style = GetSkinStyle(GetCurrentSkin());
458		const bool bMenuOpen = GetOpenMenu() != EGBMenu::None;
459		// The canvas is the viewport divided by the DPI scale; the mouse comes in viewport pixels.
460		MouseToCanvas = Canvas->SizeX > 0 ? Canvas->ClipX / (float)Canvas->SizeX : 1.f;
461	
462		// World-space numbers first: hands and HUD panels stay on top of them.
463		DrawDamageNumbers();
464		if (CVarShowElemental.GetValueOnGameThread() == 1 && Player)
465		{
466			UWorld* HudWorld = GetWorld();
467			APlayerCameraManager* CamMgr = PlayerOwner ? PlayerOwner->PlayerCameraManager.Get() : nullptr;
468			if (HudWorld && CamMgr)
469			{
470				const FVector CamLoc = CamMgr->GetCameraLocation();
471				const FVector CamFwd = CamMgr->GetCameraRotation().Vector();
472				const FVector PlayerLoc = Player->GetActorLocation();
473				for (TActorIterator<AGBEnemyCharacter> It(HudWorld); It; ++It)
474				{
475					AGBEnemyCharacter* Enemy = *It;
476					if (!Enemy || Enemy->IsDead())
477					{
478						continue;
479					}
480					if (Enemy->GetEraComponent() && !Enemy->GetEraComponent()->IsPresent())
481					{
482						continue;
483					}
484					UGBElementalStatusComponent* Elemental = Enemy->GetElementalStatus();
485					if (!Elemental)
486					{
487						continue;
488					}
489					const float Dist = FVector::Dist(PlayerLoc, Enemy->GetActorLocation());
490					if (Dist > 4000.f)
491					{
492						continue;
493					}
494					FVector Head = Enemy->GetActorLocation();
495					if (const UCapsuleComponent* Capsule = Enemy->FindComponentByClass<UCapsuleComponent>())
496					{
497						Head.Z += Capsule->GetScaledCapsuleHalfHeight() + 30.f;
498					}
499					else
500					{
501						Head.Z += 120.f;
502					}
503					if (FVector::DotProduct(Head - CamLoc, CamFwd) <= 0.f)
504					{
505						continue;
506					}
507					const FVector Screen = Canvas->Project(Head, true);
508					if (Screen.Z <= 0.f)
509					{
510						continue;
511					}
512					TArray<FString> Lines;
513					const EGBElement Elements[3] = { EGBElement::Fire, EGBElement::Lightning, EGBElement::Ice };
514					const TCHAR* Names[3] = { TEXT("Fire"), TEXT("Lightning"), TEXT("Ice") };
515					for (int32 i = 0; i < 3; ++i)
516					{
517						const EGBBuildUpPhase Phase = Elemental->GetPhase(Elements[i]);
518						if (Phase == EGBBuildUpPhase::Building)
519						{
520							const float Value = Elemental->GetBuildUp(Elements[i]);
521							if (Value <= 0.f)
522							{
523								continue;
524							}
525							const float Threshold = Elemental->GetThreshold(Elements[i]);
526							Lines.Add(FString::Printf(TEXT("%s %d/%d"), Names[i], FMath::RoundToInt(Value), FMath::RoundToInt(Threshold)));
527						}
528						else if (Phase == EGBBuildUpPhase::Active)
529						{
530							const FName Reaction = Elemental->GetReaction(Elements[i]);
531							Lines.Add(FString::Printf(TEXT("%s %s %.1fs"), Names[i], *Reaction.ToString(), Elemental->GetPhaseTimeRemaining(Elements[i])));
532						}
533						else
534						{
535							Lines.Add(FString::Printf(TEXT("%s IMMUNE %.1fs"), Names[i], Elemental->GetPhaseTimeRemaining(Elements[i])));
536						}
537					}
538					if (Enemy->GetControlLockTime() > 0.f)
539					{
540						Lines.Add(FString::Printf(TEXT("LOCK %.1fs"), Enemy->GetControlLockTime()));
541					}
542					float Y = Screen.Y;
543					for (const FString& Line : Lines)
544					{
545						DrawLabel(Line, FLinearColor::White, Screen.X, Y, 14.f, 0.5f, true, false);
546						Y += 16.f;
547					}
548				}
549			}
550		}
551		if (Player)
552		{
553			DrawHands(Player);
554			DrawStatusHud(Player, Style);
555			if (!bMenuOpen)
556			{
557				DrawCrosshair(Player, Style);
558				DrawInteractPrompt(Player);
559			}
560		}
561		if (!bMenuOpen)
562		{
563			DrawToasts();
564		}
565		if (Player && Player->GetQTE() && Player->GetQTE()->IsActive())
566		{
567			DrawQTE(Player, Style);
568		}
569		DrawDamageFlash();
570		DrawEraFade();
571		if (bMenuOpen)
572		{
573			UpdateMenuMouse();
574			DrawMenus(Player);
575			// Menu actions answer with toasts (skill unlocks, combines): keep them readable above the menu.
576			DrawToasts();
577		}
578	}
