580	// ======================================================================== hands (GDD 3: always pixel art)
581	
582	void AGBHUD::DrawHands(AGBPlayerCharacter* Player)
583	{
584		if (!Player->IsControlEnabled() || Player->IsDead())
585		{
586			return;
587		}
588		UGBPixelSpriteLibrary* Sprites = UGBPixelSpriteLibrary::Get(this);
589		if (!Sprites)
590		{
591			return;
592		}
593	
594		const float W = Canvas->ClipX;
595		const float H = Canvas->ClipY;
596		const float P = FMath::Max(1.f, (float)FMath::RoundToInt(H / GBHudLayout::HandPixelDivisor));
597	
598		// Walk bob from the horizontal speed (world time, so it slows down with the QTE).
599		const UWorld* World = GetWorld();
600		const float Time = World ? (float)World->GetTimeSeconds() : 0.f;
601		float Speed01 = 0.f;
602		if (const UCharacterMovementComponent* Move = Player->GetCharacterMovement())
603		{
604			if (Move->IsMovingOnGround())
605			{
606				Speed01 = FMath::Clamp(Player->GetVelocity().Size2D() / FMath::Max(1.f, Move->GetMaxSpeed()), 0.f, 1.f);
607			}
608		}
609		const float Phase = Time * 9.f;
610		const FVector2D Bob(FMath::Cos(Phase) * 3.f * P * Speed01, FMath::Abs(FMath::Sin(Phase)) * 2.f * P * Speed01);
611	
612		UGBEquipmentComponent* Equipment = Player->GetEquipment();
613		AGBHeldItem* Item = Equipment ? Equipment->GetActiveItem() : nullptr;
614		const FGBWeaponDefinition* WeaponDef = Item ? Item->GetDefinition() : nullptr;
615	
616		const float SinceAttack = Item ? Item->GetTimeSinceLastAttack() : 1000.f;
617		const float Kick01 = (SinceAttack >= 0.f && SinceAttack < GBHudLayout::AttackKickTime) ? 1.f - SinceAttack / GBHudLayout::AttackKickTime : 0.f;
618	
619		const UGBQTEComponent* QTE = Player->GetQTE();
620		const bool bCastPose = (QTE && QTE->IsActive()) || (GetRealTime() - LastCastTime) < GBHudLayout::CastHandTime;
621	
622		FName RightHandId(TEXT("hand_right"));
623		if (WeaponDef)
624		{
625			if (const FString* HandSprite = WeaponDef->Strings.Find(GBString::HandSprite))
626			{
627				RightHandId = FName(**HandSprite);
628			}
629		}
630		UTexture2D* HandRight = Sprites->GetSprite(RightHandId);
631		UTexture2D* HandLeft = Sprites->GetSprite(TEXT("hand_left"));
632		UTexture2D* HandCast = Sprites->GetSprite(TEXT("hand_cast"));
633		auto SizeOf = [P](UTexture2D* Texture) { return Texture ? FVector2D(Texture->GetSizeX() * P, Texture->GetSizeY() * P) : FVector2D::ZeroVector; };
634		const FVector2D RightSize = SizeOf(HandRight);
635		const FVector2D LeftSize = SizeOf(HandLeft);
636		const FVector2D CastSize = SizeOf(HandCast);
637	
638		const EGBHeldSlot Slot = Item ? Item->GetSlot() : EGBHeldSlot::Staff;
639		if (Item && Slot == EGBHeldSlot::Staff)
640		{
641			FName StaffId(TEXT("staff_apprentice"));
642			if (WeaponDef)
643			{
644				if (const FString* SpriteId = WeaponDef->Strings.Find(GBString::Sprite))
645				{
646					StaffId = FName(**SpriteId);
647				}
648			}
649			UTexture2D* Staff = Sprites->GetSprite(StaffId);
650			const FVector2D StaffSize = SizeOf(Staff);
651			// The basic attack thrusts the staff up a little.
652			const float CenterX = W * 0.72f + Bob.X;
653			const float StaffY = H - StaffSize.Y * 0.8f + Bob.Y - Kick01 * 5.f * P;
654			DrawSprite(Staff, CenterX - StaffSize.X * 0.5f, StaffY, P);
655			DrawSprite(HandRight, CenterX - RightSize.X * 0.5f, StaffY + StaffSize.Y * 0.45f, P);
656		}
657		else if (Item && Slot == EGBHeldSlot::Gun)
658		{
659			// The gun is a 3D model drawn by the world; only the hands are drawn here. Recoil pushes them down.
660			const float KickY = Kick01 * 3.f * P;
661			// Reload (both guns): the right hand follows the gun's pose, the left hand goes down with the old magazine and
662			// comes back up with the new one. Driven by the same progress as the model, so a pinned preview shows too.
663			const AGBGun* GunItem = Cast<AGBGun>(Item);
664			const bool bModelGun = GunItem && GunItem->HasViewModel();
665			const GBReloadAnim::FHandBeat Beat = bModelGun ? GunItem->GetReloadHandBeat() : GBReloadAnim::FHandBeat();
666			const float RightFollow = bModelGun ? GunItem->GetReloadPoseAmount() : 0.f;
667			const float PushY = -Beat.Push * GBHudLayout::ReloadSeatPush * P;
668			const FVector2D RightShift = (GunItem ? GunItem->GetReloadRightHandFollow() : FVector2D::ZeroVector) * (RightFollow * P);
669			DrawSprite(HandRight, W * 0.66f - RightSize.X * 0.5f + Bob.X + RightShift.X, H - RightSize.Y * 0.7f + Bob.Y + KickY + RightShift.Y + PushY, P);
670			if (!bCastPose)
671			{
672				const FVector2D Reach = (GunItem ? GunItem->GetReloadHandReach() : FVector2D::ZeroVector) * (Beat.Reach * P);
673				const float DropY = Beat.Drop * (LeftSize.Y + FMath::Abs(Reach.Y));
674				// A gun with a pump: the left hand rides the forend back and forward with it.
675				const FVector2D PumpShift = (bModelGun ? GunItem->GetPumpHandShift() : FVector2D::ZeroVector) * P;
676				DrawSprite(HandLeft, W * 0.54f - LeftSize.X * 0.5f + Bob.X + Reach.X + PumpShift.X, H - LeftSize.Y * 0.6f + Bob.Y + KickY + Reach.Y + DropY + PushY + PumpShift.Y, P);
677			}
678		}
679		else if (Item && Slot == EGBHeldSlot::Sword)
680		{
681			FName BladeId(TEXT("sword_blade"));
682			if (WeaponDef)
683			{
684				if (const FString* SpriteId = WeaponDef->Strings.Find(GBString::Sprite))
685				{
686					BladeId = FName(**SpriteId);
687				}
688			}
689			UTexture2D* Blade = Sprites->GetSprite(BladeId);
690			const FVector2D BladeSize = SizeOf(Blade);
691			const FLinearColor Tint = FMath::Lerp(GBHudLocal::White, GBHudText::ElementColor(Item->GetElement()), 0.5f);
692			// The swing moves the sword to the left.
693			const float CenterX = W * 0.70f + Bob.X - Kick01 * 12.f * P;
694			const float HandY = H - RightSize.Y * 0.75f + Bob.Y;
695			DrawSprite(Blade, CenterX - BladeSize.X * 0.5f, HandY - BladeSize.Y + 4.f * P, P, Tint);
696			DrawSprite(HandRight, CenterX - RightSize.X * 0.5f, HandY, P);
697		}
698		else
699		{
700			DrawSprite(HandRight, W * 0.72f - RightSize.X * 0.5f + Bob.X, H - RightSize.Y * 0.45f + Bob.Y, P);
701		}
702	
703		// The summoned shield is held by the left hand: while it is up (or sliding) the left hand is hidden.
704		const UGBSpellbookComponent* Spellbook = Player->GetSpellbook();
705		const bool bBlockRaised = Spellbook && Spellbook->HasShield() && Spellbook->IsBlockRaised();
706		const double Now = GetRealTime();
707		const float Dt = LastShieldUpdateTime < 0.0 ? 0.f : FMath::Clamp((float)(Now - LastShieldUpdateTime), 0.f, 0.1f);
708		LastShieldUpdateTime = Now;
709		const float Step = Dt / GBHudLayout::ShieldSlideTime;
710		ShieldRaise01 = bBlockRaised ? FMath::Min(1.f, ShieldRaise01 + Step) : FMath::Max(0.f, ShieldRaise01 - Step);
711	
712		if (bCastPose && ShieldRaise01 < 0.5f)
713		{
714			// The left hand draws the glyph: over the gun with a gun, raised at the left otherwise.
715			const float CastX = (Item && Slot == EGBHeldSlot::Gun) ? W * 0.56f : W * 0.30f;
716			DrawSprite(HandCast, CastX - CastSize.X * 0.5f + Bob.X * 0.5f, H - CastSize.Y * 1.1f + Bob.Y * 0.5f, P);
717		}
718		else if (!bCastPose && !(Item && Slot == EGBHeldSlot::Gun) && ShieldRaise01 <= 0.f)
719		{
720			DrawSprite(HandLeft, W * 0.22f - LeftSize.X * 0.5f + Bob.X, H - LeftSize.Y * 0.45f + Bob.Y, P);
721		}
722		DrawRaisedShield(Player, P, Bob);
723	}
724	
725	float AGBHUD::DrawRaisedShield(AGBPlayerCharacter* Player, float PixelSize, const FVector2D& Bob)
726	{
727		if (ShieldRaise01 <= 0.f)
728		{
729			return 0.f;
730		}
731		UGBPixelSpriteLibrary* Sprites = UGBPixelSpriteLibrary::Get(this);
732		const UGBSpellbookComponent* Spellbook = Player ? Player->GetSpellbook() : nullptr;
733		const AGBSpellActor* ShieldActor = Spellbook ? Spellbook->GetShieldActor() : nullptr;
734		FString SpriteId = ShieldActor ? ShieldActor->GetSpellCast().GetString(GBString::Sprite, TEXT("ice_shield")) : FString(TEXT("ice_shield"));
735		if (SpriteId.IsEmpty())
736		{
737			SpriteId = TEXT("ice_shield");
738		}
739		UTexture2D* Shield = Sprites ? Sprites->GetSprite(FName(*SpriteId)) : nullptr;
740		if (!Shield)
741		{
742			return ShieldRaise01;
743		}
744		const float W = Canvas->ClipX;
745		const float H = Canvas->ClipY;
746		// Whole sprite pixels, like the hands, only bigger: the shield is close to the eye.
747		const float Scale = FMath::Max(1.f, (float)FMath::RoundToInt(PixelSize * GBHudLayout::ShieldPixelMult));
748		const FVector2D Size(Shield->GetSizeX() * Scale, Shield->GetSizeY() * Scale);
749		const float Ease = FMath::InterpEaseOut(0.f, 1.f, ShieldRaise01, 2.f);
750		// Center X and top Y: from below the lower left corner up towards the middle, leaving the crosshair visible.
751		const FVector2D Lowered(W * 0.10f, H + Size.Y * 0.05f);
752		const FVector2D Raised(W * 0.36f, H * 0.40f);
753		const FVector2D Pos = FMath::Lerp(Lowered, Raised, Ease);
754		const float Health01 = Spellbook ? FMath::Clamp(Spellbook->GetShieldHealthFraction(), 0.f, 1.f) : 0.f;
755		// A worn shield is more see-through. HudTint optionally tints it (default white, so Color never changes the look here).
756		FLinearColor BaseTint(FLinearColor::White);
757		if (ShieldActor)
758		{
759			const FString HudTintStr = ShieldActor->GetSpellCast().GetString(FName(TEXT("HudTint")));
760			if (!HudTintStr.IsEmpty())
761			{
762				BaseTint = UGBDataSubsystem::ParseColor(HudTintStr, FLinearColor::White);
763			}
764		}
765		const FLinearColor Tint(BaseTint.R, BaseTint.G, BaseTint.B, FMath::Lerp(0.6f, 0.95f, Health01));
766		DrawSprite(Shield, Pos.X - Size.X * 0.5f + Bob.X * 0.5f, Pos.Y + Bob.Y * 0.5f, Scale, Tint);
767		return ShieldRaise01;
768	}
