771	
772	void AGBHUD::DrawStatusHud(AGBPlayerCharacter* Player, const FGBHudSkinStyle& Style)
773	{
774		const float W = Canvas->ClipX;
775		const float H = Canvas->ClipY;
776		const float S = UIScale();
777		const bool bShadow = !Style.bChunky;
778	
779		UGBEquipmentComponent* Equipment = Player->GetEquipment();
780		AGBHeldItem* Item = Equipment ? Equipment->GetActiveItem() : nullptr;
781		const bool bStaff = Item && Item->GetSlot() == EGBHeldSlot::Staff;
782		const bool bGun = Item && Item->GetSlot() == EGBHeldSlot::Gun;
783	
784		// Right-side info lines (quick-use item, skill points), anchored by their right edge.
785		TArray<FString> InfoLines;
786		if (const UGBInventoryComponent* Inventory = Player->GetInventory())
787		{
788			const FName QuickId = Inventory->GetQuickUseItem();
789			if (QuickId != NAME_None)
790			{
791				const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
792				const FGBItemDefinition* ItemDef = Data ? Data->FindItem(QuickId) : nullptr;
793				const FString Name = (ItemDef && !ItemDef->DisplayName.IsEmpty()) ? ItemDef->DisplayName : QuickId.ToString();
794				InfoLines.Add(FString::Printf(TEXT("[F] %s x%d"), *Name, Inventory->GetCount(QuickId)));
795			}
796			else
797			{
798				InfoLines.Add(TEXT("[F] -"));
799			}
800		}
801		if (const UGBSkillTreeComponent* SkillTree = Player->GetSkillTree())
802		{
803			if (SkillTree->GetPoints() > 0)
804			{
805				InfoLines.Add(FString::Printf(TEXT("Skill points: %d [K]"), SkillTree->GetPoints()));
806			}
807		}
808	
809		float InfoX = 0.f;
810		float InfoY = 0.f;
811		if (Style.bChunky)
812		{
813			// 90s RPG: one chunky status bar along the bottom.
814			const float BarH = 112.f * S;
815			const float Top = H - BarH;
816			DrawPanel(Style, 0.f, Top, W, BarH);
817			DrawVitals(Player, Style, 20.f * S, Top + 14.f * S, 340.f * S);
818			if (bStaff)
819			{
820				DrawSpellSlots(Player, Style, W * 0.5f, Top + 14.f * S);
821			}
822			else if (bGun)
823			{
824				DrawGunPanel(Player, Item, Style, W * 0.5f - 230.f * S, Top + 12.f * S, 460.f * S);
825			}
826			else if (Item)
827			{
828				DrawLabel(Item->GetDisplayName(), Style.Text, W * 0.5f, Top + 30.f * S, 26.f, 0.5f, bShadow);
829				DrawLabel(GBHudText::ElementName(Item->GetElement()), GBHudText::ElementColor(Item->GetElement()), W * 0.5f, Top + 62.f * S, 18.f, 0.5f, true);
830			}
831			DrawStatusEffects(Player, Style, 20.f * S, Top - 40.f * S, false);
832			DrawShieldIndicator(Player, Style, 20.f * S, Top - 90.f * S);
833			InfoX = W - 24.f * S;
834			InfoY = Top + 18.f * S;
835		}
836		else
837		{
838			// Cyberpunk: thin panels in the corners.
839			DrawPanel(Style, 24.f * S, H - 124.f * S, 380.f * S, 100.f * S);
840			DrawVitals(Player, Style, 40.f * S, H - 110.f * S, 348.f * S);
841			if (bStaff)
842			{
843				DrawSpellSlots(Player, Style, W * 0.5f, H - 100.f * S);
844			}
845			else if (bGun)
846			{
847				DrawPanel(Style, W - 404.f * S, H - 154.f * S, 380.f * S, 130.f * S);
848				DrawGunPanel(Player, Item, Style, W - 392.f * S, H - 144.f * S, 356.f * S);
849			}
850			else if (Item)
851			{
852				DrawLabel(Item->GetDisplayName(), Style.Text, W - 32.f * S, H - 70.f * S, 24.f, 1.f, bShadow);
853			}
854			DrawStatusEffects(Player, Style, 24.f * S, 24.f * S, true);
855			DrawShieldIndicator(Player, Style, 24.f * S, H - 172.f * S);
856			InfoX = W - 24.f * S;
857			InfoY = 24.f * S;
858		}
859	
860		for (const FString& Line : InfoLines)
861		{
862			DrawLabel(Line, Style.Text, InfoX, InfoY, 18.f, 1.f, bShadow);
863			InfoY += 26.f * S;
864		}
865	}
866	
867	void AGBHUD::DrawVitals(AGBPlayerCharacter* Player, const FGBHudSkinStyle& Style, float X, float Y, float W)
868	{
869		const float S = UIScale();
870		const bool bShadow = !Style.bChunky;
871		const float BarH = (Style.bChunky ? 24.f : 16.f) * S;
872		const float Gap = 8.f * S;
873		const float LabelW = 44.f * S;
874		const float BarW = W - LabelW;
875	
876		if (const UGBAttributeComponent* Attributes = Player->GetAttributes())
877		{
878			const float MaxHealth = Attributes->GetMaxHealth();
879			const float MaxMana = Attributes->GetMaxMana();
880			const float HealthFrac = MaxHealth > 0.f ? Attributes->GetHealth() / MaxHealth : 0.f;
881			const float ManaFrac = MaxMana > 0.f ? Attributes->GetMana() / MaxMana : 0.f;
882			DrawLabel(TEXT("HP"), Style.Text, X, Y + BarH * 0.5f - 9.f * S, 18.f, 0.f, bShadow);
883			DrawBar(Style, X + LabelW, Y, BarW, BarH, HealthFrac, Style.Health,
884				FString::Printf(TEXT("%d / %d"), FMath::CeilToInt(Attributes->GetHealth()), FMath::RoundToInt(MaxHealth)));
885			const float ManaY = Y + BarH + Gap;
886			DrawLabel(TEXT("MP"), Style.Text, X, ManaY + BarH * 0.5f - 9.f * S, 18.f, 0.f, bShadow);
887			DrawBar(Style, X + LabelW, ManaY, BarW, BarH, ManaFrac, Style.Mana,
888				FString::Printf(TEXT("%d / %d"), FMath::FloorToInt(Attributes->GetMana()), FMath::RoundToInt(MaxMana)));
889		}
890	
891		// Dash cooldown: a small bar that fills up; "READY" when full.
892		const float DashY = Y + 2.f * (BarH + Gap);
893		const float Remaining = Player->GetDashCooldownRemaining();
894		const UGBStatsComponent* Stats = Player->GetStats();
895		const float Total = Stats ? Stats->GetStat(GBStat::DashCooldown, 0.f) : 0.f;
896		const float DashFrac = (Remaining <= 0.f || Total <= 0.f) ? 1.f : 1.f - Remaining / Total;
897		DrawLabel(TEXT("DASH"), Style.Text, X, DashY - 3.f * S, 14.f, 0.f, bShadow);
898		DrawBar(Style, X + LabelW, DashY, BarW * 0.5f, 8.f * S, DashFrac, DashFrac >= 1.f ? Style.Accent : FLinearColor(0.4f, 0.4f, 0.4f, 1.f), FString());
899	}
