901	void AGBHUD::DrawShieldIndicator(AGBPlayerCharacter* Player, const FGBHudSkinStyle& Style, float X, float Y)
902	{
903		const UGBSpellbookComponent* Spellbook = Player->GetSpellbook();
904		if (!Spellbook || !Spellbook->HasShield())
905		{
906			return;
907		}
908		const float S = UIScale();
909		const bool bShadow = !Style.bChunky;
910		const float PW = 340.f * S;
911		const float PH = 40.f * S;
912		const FLinearColor Ice = GBHudText::ElementColor(EGBElement::Ice);
913		const bool bRaised = Spellbook->IsBlockRaised();
914		DrawPanel(Style, X, Y, PW, PH);
915		DrawLabel(TEXT("SHIELD"), bRaised ? Ice : Style.Text, X + 10.f * S, Y + 11.f * S, 16.f, 0.f, bShadow);
916		const float BarX = X + 86.f * S;
