922	
923	void AGBHUD::DrawSpellSlots(AGBPlayerCharacter* Player, const FGBHudSkinStyle& Style, float CenterX, float Y)
924	{
925		UGBSpellbookComponent* Spellbook = Player->GetSpellbook();
926		if (!Spellbook)
927		{
928			return;
929		}
930		const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
931		const float S = UIScale();
932		const float Box = (Style.bChunky ? 84.f : 66.f) * S;
933		const float Gap = 10.f * S;
934		const int32 Num = UGBSpellbookComponent::NumSlots;
935		const float X0 = CenterX - (Num * Box + (Num - 1) * Gap) * 0.5f;
936		static const TCHAR* Keys[] = { TEXT("RMB"), TEXT("1"), TEXT("2"), TEXT("3"), TEXT("4") };
937	
938		for (int32 Slot = 0; Slot < Num; ++Slot)
939		{
940			const float X = X0 + Slot * (Box + Gap);
941			DrawRect(FLinearColor(0.f, 0.f, 0.f, 0.65f), X, Y, Box, Box);
942			DrawOutline(X, Y, Box, Box, Style.bChunky ? Style.Border : Style.Border * FLinearColor(1.f, 1.f, 1.f, 0.7f), 2.f * S);
943	
944			const FName SpellId = Spellbook->GetSlotSpell(Slot);
945			const FGBSpellDefinition* Def = (Data && SpellId != NAME_None) ? Data->FindSpell(SpellId) : nullptr;
946			if (Def)
947			{
948				DrawRect(GBHudText::ElementColor(Def->Element), X + 2.f * S, Y + 2.f * S, Box - 4.f * S, 5.f * S);
949				const FString Name = GBHudText::Abbreviate(Def->DisplayName.IsEmpty() ? SpellId.ToString() : Def->DisplayName, 8);
950				DrawLabel(Name, GBHudLocal::White, X + Box * 0.5f, Y + Box * 0.36f, 15.f, 0.5f);
951				DrawLabel(FString::Printf(TEXT("%d"), FMath::RoundToInt(Spellbook->GetManaCost(SpellId))), Style.Mana + FLinearColor(0.3f, 0.3f, 0.3f, 0.f),
952					X + Box - 5.f * S, Y + Box - 20.f * S, 14.f, 1.f);
953	
954				const EGBCastFailReason Reason = Spellbook->CanCast(SpellId);
955				const float Remaining = Spellbook->GetCooldownRemaining(SpellId);
956				if (Remaining > 0.f)
957				{
958					const float Duration = Spellbook->GetCooldownDuration(SpellId);
959					const float Frac = Duration > 0.f ? FMath::Clamp(Remaining / Duration, 0.f, 1.f) : 1.f;
960					DrawRect(FLinearColor(0.f, 0.f, 0.f, 0.65f), X, Y + Box * (1.f - Frac), Box, Box * Frac);
961					DrawLabel(FString::Printf(TEXT("%.1f"), Remaining), GBHudLocal::White, X + Box * 0.5f, Y + Box * 0.5f - 12.f * S, 22.f, 0.5f);
962				}
963				else if (Reason != EGBCastFailReason::None && Reason != EGBCastFailReason::OnCooldown)
964				{
