1207			DrawRect(Fill, X, Y, Size, Size);
1208			DrawOutline(X, Y, Size, Size, bCurrent ? Style.Accent : FLinearColor(1.f, 1.f, 1.f, 0.5f), (bCurrent ? 3.f : 1.5f) * S);
1209			DrawLabel(GBHudLocal::QTEKeyLetter(Session.Sequence[i]), GBHudLocal::White, X + Size * 0.5f, Y + Size * 0.5f - 15.f * S, 28.f, 0.5f);
1210		}
1211		if (Session.Phase == EGBQTEPhase::Sequence)
1212		{
1213			DrawLabel(TEXT("Press the keys in order"), GBHudLocal::White, CX, RowY + Box + 14.f * S, 18.f, 0.5f);
1214		}
1215	
1216		// Part 2: the gesture (reach).
1217		const int32 NumGestures = Session.Gestures.Num();
1218		const int32 Judged = Session.GestureScores.Num();
1219		float ScoreSum = 0.f;
1220		for (const float Score : Session.GestureScores)
1221		{
1222			ScoreSum += Score;
1223		}
1224		if (Session.Phase == EGBQTEPhase::Gesture && Judged < NumGestures)
1225		{
1226			const EGBGesture Gesture = Session.Gestures[Judged];
1227			FString Title = GBHudLocal::GestureText(Gesture);
1228			if (NumGestures > 1)
