1234			DrawGestureHint((uint8)Gesture, CX, CY, 110.f * S, FLinearColor(1.f, 1.f, 1.f, 0.35f));
1235	
1236			// The stroke is in accumulated screen units from (0,0): draw it centered on screen, shrunk if it is too big.
1237			const TArray<FVector2D>& Stroke = Session.CurrentStroke;
1238			if (Stroke.Num() >= 2)
1239			{
1240				FVector2D Min = Stroke[0];
1241				FVector2D Max = Stroke[0];
