1266	void AGBHUD::DrawGestureHint(uint8 GestureByte, float CenterX, float CenterY, float Radius, const FLinearColor& Color)
1267	{
1268		const EGBGesture Gesture = (EGBGesture)GestureByte;
1269		const float S = UIScale();
1270		const float Thick = 4.f * S;
1271		const FVector2D C(CenterX, CenterY);
1272		auto Line = [this, &Color, Thick](const FVector2D& A, const FVector2D& B)
1273		{
1274			DrawLine(A.X, A.Y, B.X, B.Y, Color, Thick);
1275		};
1276		auto Arrowhead = [&Line, S](const FVector2D& Tip, const FVector2D& InDir)
1277		{
1278			const FVector2D Dir = InDir.GetSafeNormal();
1279			const FVector2D Normal(-Dir.Y, Dir.X);
1280			const float Len = 24.f * S;
1281			Line(Tip, Tip - Dir * Len + Normal * Len * 0.6f);
1282			Line(Tip, Tip - Dir * Len - Normal * Len * 0.6f);
1283		};
1284	
1285		FVector2D Dir = FVector2D::ZeroVector;
1286		switch (Gesture)
1287		{
1288		case EGBGesture::LineRight: Dir = FVector2D(1.f, 0.f); break;
1289		case EGBGesture::LineLeft: Dir = FVector2D(-1.f, 0.f); break;
1290		case EGBGesture::LineDown: Dir = FVector2D(0.f, 1.f); break;
1291		case EGBGesture::LineUp: Dir = FVector2D(0.f, -1.f); break;
1292		default: break;
1293		}
1294		if (!Dir.IsZero())
1295		{
1296			Line(C - Dir * Radius, C + Dir * Radius);
1297			Arrowhead(C + Dir * Radius, Dir);
1298			return;
1299		}
1300	
1301		// Circles: screen +Y is down, so a growing angle turns clockwise on screen. 300 degrees, starting at the top.
1302		const float Sign = Gesture == EGBGesture::CircleClockwise ? 1.f : -1.f;
1303		const int32 Segments = 28;
1304		const float Start = -UE_HALF_PI;
1305		const float Sweep = FMath::DegreesToRadians(300.f);
1306		FVector2D Prev = C + FVector2D(FMath::Cos(Start), FMath::Sin(Start)) * Radius;
1307		float Angle = Start;
1308		for (int32 i = 1; i <= Segments; ++i)
1309		{
1310			Angle = Start + Sign * Sweep * i / Segments;
1311			const FVector2D Next = C + FVector2D(FMath::Cos(Angle), FMath::Sin(Angle)) * Radius;
1312			Line(Prev, Next);
1313			Prev = Next;
1314		}
1315		Arrowhead(Prev, FVector2D(-FMath::Sin(Angle), FMath::Cos(Angle)) * Sign);
1316	}
