210	void AGBHUD::UpdateMenuMouse()
211	{
212		APlayerController* PC = GetOwningPlayerController();
213		float MouseX = 0.f;
214		float MouseY = 0.f;
215		if (!PC || !PC->GetMousePosition(MouseX, MouseY))
216		{
217			return;
218		}
219		const FVector2D Mouse(MouseX * MouseToCanvas, MouseY * MouseToCanvas);
220		const bool bMoved = bHasMenuMouse && !Mouse.Equals(LastMenuMouse, 0.5f);
221		LastMenuMouse = Mouse;
222		bHasMenuMouse = true;
223		// Hover uses last frame's clickables, so the highlight moves in the same frame it is drawn.
224		if (bMoved && MenuHitsMenu == GetOpenMenu())
225		{
226			if (const FMenuHit* Hit = FindMenuHit(Mouse))
227			{
228				ApplyMenuHover(*Hit);
229			}
230		}
231	}
232	
233	void AGBHUD::ApplyMenuHover(const FMenuHit& Hit)
234	{
235		switch (Hit.Kind)
236		{
237		case EMenuHitKind::PauseEntry:
238		case EMenuHitKind::ItemRow:
239		case EMenuHitKind::WeaponRow:
240			MenuState.Cursor = Hit.Index;
241			break;
242		case EMenuHitKind::SpellSlot:
243			if (!MenuState.bChoosingSpell)
244			{
245				MenuState.Cursor = Hit.Index;
246			}
247			break;
248		case EMenuHitKind::SpellChoice:
249			MenuState.SubCursor = Hit.Index;
250			break;
251		case EMenuHitKind::SkillNode:
252			MenuState.SkillCursor = Hit.Id;
253			break;
254		case EMenuHitKind::Tab:
255		case EMenuHitKind::SkillReset:
256		case EMenuHitKind::SkillAddPoint:
257		default:
258			// Tabs, the skill buttons (reset, +1 point) and the death screen only react to clicks.
259			break;
260		}
261	}
262	
263	void AGBHUD::ActivateMenuHit(const FMenuHit& Hit)
264	{
265		AGBPlayerCharacter* Player = GetPlayer();
266		switch (Hit.Kind)
267		{
268		case EMenuHitKind::PauseEntry:
269			MenuState.Cursor = Hit.Index;
270			MenuConfirm();
271			break;
272		case EMenuHitKind::Tab:
273			if (Hit.Index != MenuState.Page)
274			{
275				SetInventoryPage(Hit.Index);
276			}
277			break;
278		case EMenuHitKind::ItemRow:
279			MenuState.Cursor = Hit.Index;
280			ConfirmItem(Player);
281			break;
282		case EMenuHitKind::WeaponRow:
283			MenuState.Cursor = Hit.Index;
284			ConfirmWeapon(Player);
285			break;
286		case EMenuHitKind::SpellSlot:
287			// A click on another slot while choosing leaves the chooser and opens it for that slot.
288			MenuState.bChoosingSpell = false;
289			MenuState.Cursor = Hit.Index;
290			ConfirmSpellSlot(Player);
291			break;
292		case EMenuHitKind::SpellChoice:
293			MenuState.SubCursor = Hit.Index;
294			ConfirmSpellSlot(Player);
295			break;
296		case EMenuHitKind::SkillNode:
297			MenuState.SkillCursor = Hit.Id;
298			ConfirmSkill(Player);
299			break;
300		case EMenuHitKind::SkillReset:
301			ResetSkills(Player);
302			break;
303		case EMenuHitKind::SkillAddPoint:
304			AddTestSkillPoint(Player);
305			break;
306		case EMenuHitKind::DeathScreen:
307			// The controller handles the respawn confirm (AGBPlayerController::InputMenuClick): nothing here,
308			// so a click respawns exactly once.
309			break;
310		}
311	}
312	
313	bool AGBHUD::MenuClick(const FVector2D& ScreenPosition)
314	{
315		const EGBMenu Menu = GetOpenMenu();
316		// Only the clickables of the screen that is showing right now (not of a page left this frame).
317		if (Menu == EGBMenu::None || Menu != MenuHitsMenu || MenuHitsPage != MenuState.Page || bMenuHitsChoosing != MenuState.bChoosingSpell)
318		{
319			return false;
320		}
321		const FVector2D Position = ScreenPosition * MouseToCanvas;
322		const FMenuHit* Found = FindMenuHit(Position);
323		if (!Found)
324		{
325			return false;
326		}
327		// Copy: the action may change the menu, and the list is rebuilt on the next draw.
328		const FMenuHit Hit = *Found;
329		ActivateMenuHit(Hit);
330		return true;
331	}
332	
333	void AGBHUD::MenuNavigate(FIntPoint Direction)
334	{
335		using namespace GBHudMenuLocal;
336		AGBPlayerCharacter* Player = GetPlayer();
337		switch (GetOpenMenu())
338		{
339		case EGBMenu::Pause:
340			if (Direction.Y != 0)
341			{
342				MenuState.Cursor = Wrap(MenuState.Cursor + Direction.Y, 2);
343			}
344			break;
345		case EGBMenu::SkillTrees:
346			NavigateSkills(Direction);
347			break;
348		case EGBMenu::Inventory:
349			if (MenuState.Page == PageSkills)
350			{
351				NavigateSkills(Direction);
352			}
353			else if (MenuState.Page == PageSpells)
354			{
355				if (Direction.Y == 0)
356				{
357					break;
358				}
359				if (MenuState.bChoosingSpell)
360				{
361					MenuState.SubCursor = Wrap(MenuState.SubCursor + Direction.Y, GetAssignableSpells(Player).Num());
362				}
363				else
364				{
365					MenuState.Cursor = Wrap(MenuState.Cursor + Direction.Y, UGBSpellbookComponent::NumSlots + 1);
366				}
367			}
368			else if (MenuState.Page == PageWeapons)
369			{
370				if (Direction.Y != 0)
371				{
372					MenuState.Cursor = Wrap(MenuState.Cursor + Direction.Y, GetWeaponList(Player).Num());
373				}
374			}
375			else if (Direction.Y != 0)
376			{
377				MenuState.Cursor = Wrap(MenuState.Cursor + Direction.Y, GetInventoryList(Player).Num());
378			}
379			break;
380		default:
381			break;
382		}
383	}
384	
385	void AGBHUD::MenuConfirm()
386	{
387		AGBPlayerCharacter* Player = GetPlayer();
388		switch (GetOpenMenu())
389		{
390		case EGBMenu::Pause:
391			if (MenuState.Cursor == 0)
392			{
393				if (AGBPlayerController* PC = GetGBController())
394				{
395					PC->SetMenu(EGBMenu::None);
396				}
397			}
398			else
399			{
400				UKismetSystemLibrary::QuitGame(this, GetOwningPlayerController(), EQuitPreference::Quit, false);
401			}
402			break;
403		case EGBMenu::SkillTrees:
404			ConfirmSkill(Player);
405			break;
406		case EGBMenu::Inventory:
407			if (MenuState.Page == PageItems)
408			{
409				ConfirmItem(Player);
410			}
411			else if (MenuState.Page == PageWeapons)
412			{
413				ConfirmWeapon(Player);
414			}
415			else if (MenuState.Page == PageSpells)
416			{
417				ConfirmSpellSlot(Player);
418			}
419			else
420			{
421				ConfirmSkill(Player);
422			}
423			break;
424		default:
425			// Death: the controller handles the respawn confirm.
426			break;
427		}
428	}
429	
430	bool AGBHUD::MenuBack()
431	{
432		switch (GetOpenMenu())
433		{
434		case EGBMenu::Inventory:
435			if (MenuState.Page == PageItems && MenuState.PendingCombine != NAME_None)
436			{
437				MenuState.PendingCombine = NAME_None;
438				return true;
439			}
440			if (MenuState.Page == PageSpells && MenuState.bChoosingSpell)
441			{
442				MenuState.bChoosingSpell = false;
443				return true;
444			}
445			return false;
446		case EGBMenu::Death:
447			// The death screen only closes by respawning.
448			return true;
449		default:
450			return false;
451		}
452	}
453	
454	void AGBHUD::MenuTab(int32 Direction)
455	{
456		if (Direction == 0)
457		{
458			return;
459		}
460		const EGBMenu Menu = GetOpenMenu();
461		if (Menu == EGBMenu::Inventory)
462		{
463			SetInventoryPage(MenuState.Page + Direction);
464		}
465		else if (Menu == EGBMenu::SkillTrees)
466		{
467			// Jump to the first node of the other tree.
468			const TArray<FSkillNodeRef> Nodes = GetSkillNodes();
469			const FSkillNodeRef* Current = Nodes.FindByPredicate([this](const FSkillNodeRef& Node) { return Node.Id == MenuState.SkillCursor; });
470			const int32 OtherTree = Current ? 1 - Current->Tree : 0;
471			if (const FSkillNodeRef* Other = Nodes.FindByPredicate([OtherTree](const FSkillNodeRef& Node) { return Node.Tree == OtherTree; }))
472			{
473				MenuState.SkillCursor = Other->Id;
474			}
475		}
476	}
477	
478	// ======================================================================== lists
479	
480	TArray<FName> AGBHUD::GetInventoryList(AGBPlayerCharacter* Player) const
481	{
482		TArray<FName> Result;
483		const UGBInventoryComponent* Inventory = Player ? Player->GetInventory() : nullptr;
484		if (!Inventory)
485		{
486			return Result;
487		}
488		if (const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this))
489		{
490			for (const FGBItemDefinition& Def : Data->GetItems())
491			{
492				if (Inventory->GetCount(Def.Id) > 0)
493				{
494					Result.Add(Def.Id);
495				}
496			}
497		}
498		// Items no longer in the data (after a reload) are still listed, at the end.
499		for (const TPair<FName, int32>& Entry : Inventory->GetItems())
500		{
501			if (Entry.Value > 0 && !Result.Contains(Entry.Key))
502			{
503				Result.Add(Entry.Key);
504			}
505		}
506		return Result;
507	}
508	
509	TArray<FName> AGBHUD::GetWeaponList(AGBPlayerCharacter* Player) const
510	{
511		TArray<FName> Result;
512		const UGBEquipmentComponent* Equipment = Player ? Player->GetEquipment() : nullptr;
513		if (!Equipment)
514		{
515			return Result;
516		}
517		const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
518		static const EGBHeldSlot Order[] = { EGBHeldSlot::Staff, EGBHeldSlot::Gun, EGBHeldSlot::Sword };
519		for (const EGBHeldSlot Slot : Order)
520		{
521			for (const FName& WeaponId : Equipment->GetOwnedWeapons())
522			{
523				const FGBWeaponDefinition* Def = Data ? Data->FindWeapon(WeaponId) : nullptr;
524				if (Def && Def->Slot == Slot)
525				{
526					Result.AddUnique(WeaponId);
527				}
528			}
529		}
530		// Weapons no longer in the data (after a reload) are still listed, at the end.
531		for (const FName& WeaponId : Equipment->GetOwnedWeapons())
532		{
533			if (WeaponId != NAME_None)
534			{
535				Result.AddUnique(WeaponId);
536			}
537		}
538		return Result;
539	}
540	
541	TArray<FName> AGBHUD::GetAssignableSpells(AGBPlayerCharacter* Player) const
542	{
543		TArray<FName> Result;
544		Result.Add(NAME_None);
545		const UGBSpellbookComponent* Spellbook = Player ? Player->GetSpellbook() : nullptr;
546		const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
547		if (!Spellbook || !Data)
548		{
549			return Result;
550		}
551		for (const FName& SpellId : Spellbook->GetKnownSpells())
552		{
553			const FGBSpellDefinition* Def = Data->FindSpell(SpellId);
554			if (Def && !Def->bPassive && !Def->bRequiresGun && SpellId != Spellbook->GetEnchantSpell())
555			{
556				Result.Add(SpellId);
557			}
558		}
559		return Result;
560	}
561	
562	TArray<AGBHUD::FSkillNodeRef> AGBHUD::GetSkillNodes() const
563	{
564		TArray<FSkillNodeRef> Result;
565		if (const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this))
566		{
567			for (const FGBSkillNodeDefinition& Def : Data->GetSkillNodes())
568			{
569				FSkillNodeRef Ref;
570				Ref.Id = Def.Id;
571				Ref.Tree = GBHudMenuLocal::IsWeaponTree(Def.Tree) ? 1 : 0;
572				Ref.Column = FMath::Max(0, Def.Column);
573				Ref.Row = FMath::Max(0, Def.Row);
574				Result.Add(Ref);
575			}
576		}
577		return Result;
578	}
579	
580	void AGBHUD::NavigateSkills(FIntPoint Direction)
581	{
582		const TArray<FSkillNodeRef> Nodes = GetSkillNodes();
583		if (Nodes.Num() == 0 || Direction == FIntPoint::ZeroValue)
584		{
585			return;
586		}
587		const FSkillNodeRef* Current = Nodes.FindByPredicate([this](const FSkillNodeRef& Node) { return Node.Id == MenuState.SkillCursor; });
588		if (!Current)
589		{
590			MenuState.SkillCursor = Nodes[0].Id;
591			return;
592		}
593	
594		// Both trees on one grid (the weapon tree to the right of the spell tree); pick the nearest node in the pressed direction.
595		int32 MaxSpellColumn = 0;
596		for (const FSkillNodeRef& Node : Nodes)
597		{
598			if (Node.Tree == 0)
599			{
600				MaxSpellColumn = FMath::Max(MaxSpellColumn, Node.Column);
601			}
602		}
603		auto GridPos = [MaxSpellColumn](const FSkillNodeRef& Node)
604		{
605			return FVector2D(Node.Tree * (MaxSpellColumn + 2) + Node.Column, Node.Row);
606		};
607		const FVector2D Dir(Direction.X, Direction.Y);
608		const FVector2D From = GridPos(*Current);
609		float BestCost = TNumericLimits<float>::Max();
610		FName Best = NAME_None;
611		for (const FSkillNodeRef& Node : Nodes)
612		{
613			if (Node.Id == Current->Id)
614			{
615				continue;
616			}
617			const FVector2D Delta = GridPos(Node) - From;
618			const float Along = FVector2D::DotProduct(Delta, Dir);
619			if (Along <= 0.f)
620			{
621				continue;
622			}
623			const float Across = FMath::Abs(FVector2D::CrossProduct(Delta, Dir));
624			const float Cost = Along + 2.f * Across;
625			if (Cost < BestCost)
626			{
627				BestCost = Cost;
628				Best = Node.Id;
629			}
630		}
631		if (Best != NAME_None)
632		{
633			MenuState.SkillCursor = Best;
634		}
635	}
636	
637	// ======================================================================== confirm actions
638	
639	void AGBHUD::ConfirmItem(AGBPlayerCharacter* Player)
640	{
641		using namespace GBHudMenuLocal;
642		UGBInventoryComponent* Inventory = Player ? Player->GetInventory() : nullptr;
643		const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
644		const TArray<FName> List = GetInventoryList(Player);
645		if (!Inventory || List.Num() == 0)
646		{
647			return;
648		}
649		MenuState.Cursor = FMath::Clamp(MenuState.Cursor, 0, List.Num() - 1);
650		const FName ItemId = List[MenuState.Cursor];
651		const FGBItemDefinition* Def = Data ? Data->FindItem(ItemId) : nullptr;
652		if (!Def)
653		{
654			ShowMessage(TEXT("Unknown item"), 1.5f);
655			return;
656		}
657	
658		switch (Def->Type)
659		{
660		case EGBItemType::Consumable:
661			if (!Inventory->UseItem(ItemId))
662			{
663				ShowMessage(TEXT("Cannot use that now"), 1.5f);
664			}
665			break;
666		case EGBItemType::Throwable:
667			ShowMessage(TEXT("Throw it with [F] (quick-use)"), 2.f);
668			break;
669		case EGBItemType::Armor:
670			if (!Inventory->EquipArmor(Inventory->GetEquippedArmor() == ItemId ? NAME_None : ItemId))
671			{
672				ShowMessage(TEXT("Cannot equip that"), 1.5f);
673			}
674			break;
675		case EGBItemType::Material:
676		case EGBItemType::KeyItem:
677			if (MenuState.PendingCombine == NAME_None)
678			{
679				MenuState.PendingCombine = ItemId;
680			}
681			else if (MenuState.PendingCombine == ItemId)
682			{
683				MenuState.PendingCombine = NAME_None;
684			}
685			else
686			{
687				const FName Other = MenuState.PendingCombine;
688				MenuState.PendingCombine = NAME_None;
689				const FGBRecipeDefinition* Recipe = Inventory->FindRecipe(Other, ItemId);
690				// Copy what the toast needs before combining: the recipe pointer belongs to the data tables.
691				FString ResultName;
692				if (Recipe)
693				{
694					if (Recipe->ResultItem != NAME_None)
695					{
696						ResultName = ItemName(Data, Recipe->ResultItem);
697					}
698					else if (Recipe->ResultWeapon != NAME_None)
699					{
700						const FGBWeaponDefinition* Weapon = Data->FindWeapon(Recipe->ResultWeapon);
701						ResultName = (Weapon && !Weapon->DisplayName.IsEmpty()) ? Weapon->DisplayName : Recipe->ResultWeapon.ToString();
702					}
703				}
704				if (Recipe && Inventory->TryCombine(Other, ItemId))
705				{
706					ShowMessage(ResultName.IsEmpty() ? FString(TEXT("Combined")) : FString::Printf(TEXT("Created %s"), *ResultName), 2.5f);
707				}
708				else
709				{
710					ShowMessage(TEXT("These do not combine"), 1.5f);
711				}
712			}
713			break;
714		default:
715			break;
716		}
717	}
718	
719	void AGBHUD::ConfirmWeapon(AGBPlayerCharacter* Player)
720	{
721		UGBEquipmentComponent* Equipment = Player ? Player->GetEquipment() : nullptr;
722		const TArray<FName> List = GetWeaponList(Player);
723		if (!Equipment || List.Num() == 0)
724		{
725			return;
726		}
727		MenuState.Cursor = FMath::Clamp(MenuState.Cursor, 0, List.Num() - 1);
728		const FName WeaponId = List[MenuState.Cursor];
729		const FString Name = GBHudMenuLocal::WeaponName(UGBDataSubsystem::Get(this), WeaponId);
730		if (Equipment->IsWeaponEquipped(WeaponId))
731		{
732			ShowMessage(FString::Printf(TEXT("%s is already equipped"), *Name), 1.5f);
733		}
734		else if (Equipment->EquipOwnedWeapon(WeaponId))
735		{
736			ShowMessage(FString::Printf(TEXT("Equipped %s"), *Name), 2.f);
737		}
738		else
739		{
740			ShowMessage(TEXT("Cannot change weapons right now"), 1.5f);
741		}
742	}
743	
744	void AGBHUD::ConfirmSpellSlot(AGBPlayerCharacter* Player)
745	{
746		UGBSpellbookComponent* Spellbook = Player ? Player->GetSpellbook() : nullptr;
747		if (!Spellbook)
748		{
749			return;
750		}
751		const int32 NumSlots = UGBSpellbookComponent::NumSlots;
752		if (MenuState.bChoosingSpell)
753		{
754			const TArray<FName> Options = GetAssignableSpells(Player);
755			if (Options.IsValidIndex(MenuState.SubCursor) && MenuState.Cursor < NumSlots)
756			{
757				if (!Spellbook->EquipSpell(MenuState.Cursor, Options[MenuState.SubCursor]))
758				{
759					ShowMessage(TEXT("Cannot equip that spell"), 1.5f);
760				}

