762			MenuState.bChoosingSpell = false;
763		}
764		else if (MenuState.Cursor < NumSlots)
765		{
766			const TArray<FName> Options = GetAssignableSpells(Player);
767			MenuState.bChoosingSpell = true;
768			MenuState.SubCursor = FMath::Max(0, Options.IndexOfByKey(Spellbook->GetSlotSpell(MenuState.Cursor)));
769		}
770		else
771		{
772			// The enchant slot: cycle its element Fire -> Lightning -> Ice.
773			EGBElement Next = EGBElement::Fire;
774			switch (Spellbook->GetEnchantElement())
