848	float AGBHUD::DrawWrapped(const FString& Text, const FLinearColor& Color, float X, float Y, float MaxWidth, float SizePx, bool bShadow)
849	{
850		TArray<FString> Words;
851		Text.ParseIntoArrayWS(Words);
852		const float LineH = FMath::Max(MeasureLabel(TEXT("Ag"), SizePx).Y, 1.f);
853		float CurY = Y;
854		FString Line;
855		for (const FString& Word : Words)
856		{
857			const FString Candidate = Line.IsEmpty() ? Word : Line + TEXT(" ") + Word;
858			if (!Line.IsEmpty() && MeasureLabel(Candidate, SizePx).X > MaxWidth)
859			{
860				DrawLabel(Line, Color, X, CurY, SizePx, 0.f, bShadow);
861				CurY += LineH;
862				Line = Word;
863			}
864			else
865			{
866				Line = Candidate;
867			}
868		}
869		if (!Line.IsEmpty())
870		{
871			DrawLabel(Line, Color, X, CurY, SizePx, 0.f, bShadow);
872			CurY += LineH;
873		}
874		return CurY - Y;
875	}
