954	void AGBHUD::DrawInventory(AGBPlayerCharacter* Player, const FGBHudSkinStyle& Style)
955	{
956		const float S = UIScale();
957		const float W = Canvas->ClipX;
958		const float H = Canvas->ClipY;
959		const bool bShadow = !Style.bChunky;
960		DrawRect(GBHudMenuLocal::MenuDim, 0.f, 0.f, W, H);
961	
962		const float PX = W * 0.07f;
963		const float PY = H * 0.06f;
964		const float PW = W * 0.86f;
965		const float PH = H * 0.88f;
966		DrawPanel(Style, PX, PY, PW, PH);
967	
968		// Tabs.
969		static const TCHAR* Tabs[] = { TEXT("Items"), TEXT("Weapons"), TEXT("Spells"), TEXT("Skills") };
970		static_assert((int32)UE_ARRAY_COUNT(Tabs) == PageCount,"One tab name per inventory page");
971		float TabX = PX + 24.f * S;
972		for (int32 i = 0; i < PageCount; ++i)
973		{
974			const FVector2D Size = MeasureLabel(Tabs[i], 24.f);
975			const bool bSelected = MenuState.Page == i;
976			if (bSelected)
977			{
978				DrawRect(Style.Accent * FLinearColor(1.f, 1.f, 1.f, 0.45f), TabX - 10.f * S, PY + 14.f * S, Size.X + 20.f * S, Size.Y + 8.f * S);
979			}
980			AddMenuHit(EMenuHitKind::Tab, TabX - 10.f * S, PY + 14.f * S, Size.X + 20.f * S, Size.Y + 8.f * S, i);
981			DrawLabel(Tabs[i], Style.Text, TabX, PY + 18.f * S, 24.f, 0.f, bShadow);
982			TabX += Size.X + 44.f * S;
983		}
984		DrawLabel(TEXT("Q / E or click a tab: switch page   Esc: close"), Style.Text, PX + PW - 24.f * S, PY + 22.f * S, 16.f, 1.f, bShadow);
985	
986		if (!Player)
987		{
988			return;
989		}
990		const float CX = PX + 24.f * S;
991		const float CY = PY + 70.f * S;
992		const float CW = PW - 48.f * S;
993		const float CH = PH - 100.f * S;
994		if (MenuState.Page == PageItems)
995		{
996			DrawItemsPage(Player, Style, CX, CY, CW, CH);
997		}
998		else if (MenuState.Page == PageWeapons)
999		{
1000			DrawWeaponsPage(Player, Style, CX, CY, CW, CH);
1001		}
1002		else if (MenuState.Page == PageSpells)
1003		{
1004			DrawSpellsPage(Player, Style, CX, CY, CW, CH);
1005		}
1006		else
1007		{
1008			DrawSkillTrees(Player, CY);
1009		}
1010	}
