1012	void AGBHUD::DrawItemsPage(AGBPlayerCharacter* Player, const FGBHudSkinStyle& Style, float X, float Y, float W, float H)
1013	{
1014		using namespace GBHudMenuLocal;
1015		const float S = UIScale();
1016		const bool bShadow = !Style.bChunky;
1017		const UGBInventoryComponent* Inventory = Player->GetInventory();
1018		const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
1019		const TArray<FName> List = GetInventoryList(Player);
1020		if (!Inventory || List.Num() == 0)
1021		{
1022			DrawLabel(TEXT("Your bag is empty."), Style.Text, X, Y, 22.f, 0.f, bShadow);
1023			return;
1024		}
1025		MenuState.Cursor = FMath::Clamp(MenuState.Cursor, 0, List.Num() - 1);
1026	
1027		const float ListW = W * 0.5f;
1028		const float RowH = 34.f * S;
1029		const int32 Visible = FMath::Max(1, FMath::FloorToInt(H / RowH));
1030		const int32 First = FMath::Clamp(MenuState.Cursor - Visible + 1, 0, FMath::Max(0, List.Num() - Visible));
1031		for (int32 i = First; i < List.Num() && i < First + Visible; ++i)
1032		{
1033			const FName ItemId = List[i];
1034			const float RowY = Y + (i - First) * RowH;
1035			if (i == MenuState.Cursor)
1036			{
1037				DrawRect(Style.Accent * FLinearColor(1.f, 1.f, 1.f, 0.35f), X - 6.f * S, RowY - 3.f * S, ListW, RowH - 2.f * S);
1038			}
1039			AddMenuHit(EMenuHitKind::ItemRow, X - 6.f * S, RowY - 3.f * S, ListW, RowH - 2.f * S, i);
1040			FString Text = FString::Printf(TEXT("%s  x%d"), *ItemName(Data, ItemId), Inventory->GetCount(ItemId));
1041			if (Inventory->GetEquippedArmor() == ItemId)
1042			{
1043				Text += TEXT("  [Equipped]");
1044			}
1045			if (Inventory->GetQuickUseItem() == ItemId)
1046			{
1047				Text += TEXT("  [F]");
1048			}
1049			if (MenuState.PendingCombine == ItemId)
1050			{
1051				Text = TEXT("* ") + Text;
1052			}
1053			DrawLabel(Text, Style.Text, X, RowY, 20.f, 0.f, bShadow);
1054		}
1055	
1056		// Details of the selected item.
1057		const FName Selected = List[MenuState.Cursor];
1058		const FGBItemDefinition* Def = Data ? Data->FindItem(Selected) : nullptr;
1059		const float DX = X + ListW + 30.f * S;
1060		const float DW = W - ListW - 30.f * S;
1061		float DY = Y;
1062		DrawLabel(ItemName(Data, Selected), Style.Text, DX, DY, 28.f, 0.f, bShadow, true);
1063		DY += 44.f * S;
1064		if (Def)
1065		{
1066			DrawLabel(ItemTypeName(Def->Type), Style.Text, DX, DY, 18.f, 0.f, bShadow);
1067			DY += 32.f * S;
1068			DY += DrawWrapped(Def->Description, Style.Text, DX, DY, DW, 18.f, bShadow) + 20.f * S;
1069	
1070			FString Hint;
1071			switch (Def->Type)
1072			{
1073			case EGBItemType::Consumable: Hint = TEXT("Click or Enter: use"); break;
1074			case EGBItemType::Throwable: Hint = TEXT("Throw it with [F] (quick-use, Shift cycles)"); break;
1075			case EGBItemType::Armor: Hint = Inventory->GetEquippedArmor() == Selected ? TEXT("Click or Enter: unequip") : TEXT("Click or Enter: equip"); break;
1076			case EGBItemType::Material:
1077			case EGBItemType::KeyItem:
1078				if (MenuState.PendingCombine == NAME_None)
1079				{
1080					Hint = TEXT("Click or Enter: combine with another item");
1081				}
1082				else if (MenuState.PendingCombine == Selected)
1083				{
1084					Hint = TEXT("Choose the second item (Esc: cancel)");
1085				}
1086				else
1087				{
1088					Hint = FString::Printf(TEXT("Click or Enter: combine with %s"), *ItemName(Data, MenuState.PendingCombine));
1089				}
1090				break;
1091			default: break;
1092			}
1093			DrawLabel(Hint, Style.Accent, DX, DY, 18.f, 0.f, true);
1094		}
1095	}
