1097	void AGBHUD::DrawWeaponsPage(AGBPlayerCharacter* Player, const FGBHudSkinStyle& Style, float X, float Y, float W, float H)
1098	{
1099		using namespace GBHudMenuLocal;
1100		const float S = UIScale();
1101		const bool bShadow = !Style.bChunky;
1102		const UGBEquipmentComponent* Equipment = Player->GetEquipment();
1103		const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
1104		const TArray<FName> List = GetWeaponList(Player);
1105		if (!Equipment || List.Num() == 0)
1106		{
1107			DrawLabel(TEXT("You carry no weapons."), Style.Text, X, Y, 22.f, 0.f, bShadow);
1108			return;
1109		}
1110		MenuState.Cursor = FMath::Clamp(MenuState.Cursor, 0, List.Num() - 1);
1111	
1112		// Display rows: a header before each kind, then its weapons. WeaponIndex -1 = header.
1113		struct FRow
1114		{
1115			FString Text;
1116			int32 WeaponIndex = -1;
1117		};
1118		TArray<FRow> Rows;
1119		FString LastGroup;
1120		int32 CursorRow = 0;
1121		for (int32 i = 0; i < List.Num(); ++i)
1122		{
1123			const FGBWeaponDefinition* Def = Data ? Data->FindWeapon(List[i]) : nullptr;
1124			const FString Group = Def ? SlotName(Def->Slot, true) : FString(TEXT("Other"));
1125			if (Group != LastGroup)
1126			{
1127				Rows.Add(FRow{ Group, -1 });
1128				LastGroup = Group;
1129			}
1130			if (i == MenuState.Cursor)
1131			{
1132				CursorRow = Rows.Num();
1133			}
1134			Rows.Add(FRow{ WeaponName(Data, List[i]), i });
1135		}
1136	
1137		const float ListW = W * 0.5f;
1138		const float RowH = 34.f * S;
1139		const int32 Visible = FMath::Max(1, FMath::FloorToInt(H / RowH));
1140		const int32 First = FMath::Clamp(CursorRow - Visible + 1, 0, FMath::Max(0, Rows.Num() - Visible));
1141		for (int32 r = First; r < Rows.Num() && r < First + Visible; ++r)
1142		{
1143			const FRow& Row = Rows[r];
1144			const float RowY = Y + (r - First) * RowH;
1145			if (Row.WeaponIndex < 0)
1146			{
1147				DrawLabel(Row.Text.ToUpper(), Style.Text, X, RowY + 6.f * S, 16.f, 0.f, bShadow, true);
1148				continue;
1149			}
1150			const FName WeaponId = List[Row.WeaponIndex];
1151			if (Row.WeaponIndex == MenuState.Cursor)
1152			{
1153				DrawRect(Style.Accent * FLinearColor(1.f, 1.f, 1.f, 0.35f), X - 6.f * S, RowY - 3.f * S, ListW, RowH - 2.f * S);
1154			}
1155			AddMenuHit(EMenuHitKind::WeaponRow, X - 6.f * S, RowY - 3.f * S, ListW, RowH - 2.f * S, Row.WeaponIndex);
1156			const bool bEquipped = Equipment->IsWeaponEquipped(WeaponId);
1157			DrawLabel(bEquipped ? FString::Printf(TEXT("   %s  [equipped]"), *Row.Text) : TEXT("   ") + Row.Text, Style.Text, X, RowY, 20.f, 0.f, bShadow);
1158			if (const FGBWeaponDefinition* Def = Data ? Data->FindWeapon(WeaponId) : nullptr)
1159			{
1160				(void)Def;
1161				const EGBElement Element = Equipment->GetWeaponElement(WeaponId);
1162				DrawLabel(GBHudText::ElementName(Element), GBHudText::ElementColor(Element), X + ListW - 18.f * S, RowY + 2.f * S, 16.f, 1.f, true);
1163			}
1164		}
1165	
1166		// Details of the selected weapon.
1167		const FName Selected = List[MenuState.Cursor];
1168		const FGBWeaponDefinition* Def = Data ? Data->FindWeapon(Selected) : nullptr;
1169		const float DX = X + ListW + 30.f * S;
1170		const float DW = W - ListW - 30.f * S;
1171		float DY = Y;
1172		DrawLabel(WeaponName(Data, Selected), Style.Text, DX, DY, 28.f, 0.f, bShadow, true);
1173		DY += 44.f * S;
1174		if (!Def)
1175		{
1176			DrawLabel(TEXT("Unknown weapon"), Style.Text, DX, DY, 18.f, 0.f, bShadow);
1177			return;
1178		}
1179		DrawLabel(FString::Printf(TEXT("%s   %s"), *SlotName(Def->Slot, false), *GBHudText::ElementName(Equipment->GetWeaponElement(Selected))),
1180			GBHudText::ElementColor(Equipment->GetWeaponElement(Selected)), DX, DY, 18.f, 0.f, true);
1181		DY += 32.f * S;
1182		for (const FString& Line : WeaponStatLines(*Def))
1183		{
1184			DrawLabel(Line, Style.Text, DX, DY, 18.f, 0.f, bShadow);
1185			DY += 28.f * S;
1186		}
1187		DY += 16.f * S;
1188	
1189		if (Equipment->IsWeaponEquipped(Selected))
1190		{
1191			DrawLabel(FString::Printf(TEXT("Equipped in the %s slot"), *SlotName(Def->Slot, false).ToLower()), Style.Accent, DX, DY, 18.f, 0.f, true);
1192		}
1193		else
1194		{
1195			const AGBHeldItem* Current = Equipment->GetItemInSlot(Def->Slot);
1196			const FString Hint = Current ? FString::Printf(TEXT("Click or Enter: equip (replaces %s)"), *Current->GetDisplayName())
1197				: FString(TEXT("Click or Enter: equip"));
1198			DrawWrapped(Hint, Style.Accent, DX, DY, DW, 18.f, true);
1199		}
1200	}
