1202	void AGBHUD::DrawSpellsPage(AGBPlayerCharacter* Player, const FGBHudSkinStyle& Style, float X, float Y, float W, float H)
1203	{
1204		using namespace GBHudMenuLocal;
1205		const float S = UIScale();
1206		const bool bShadow = !Style.bChunky;
1207		UGBSpellbookComponent* Spellbook = Player->GetSpellbook();
1208		const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
1209		if (!Spellbook)
1210		{
1211			return;
1212		}
1213		const int32 NumSlots = UGBSpellbookComponent::NumSlots;
1214		const float ListW = W * 0.45f;
1215		const float RowH = 42.f * S;
1216	
1217		DrawLabel(TEXT("Loadout"), Style.Text, X, Y, 22.f, 0.f, bShadow, true);
1218		const float ListY = Y + 44.f * S;
1219		for (int32 i = 0; i <= NumSlots; ++i)
1220		{
1221			const float RowY = ListY + i * RowH;
1222			if (i == MenuState.Cursor)
1223			{
1224				DrawRect(Style.Accent * FLinearColor(1.f, 1.f, 1.f, MenuState.bChoosingSpell ? 0.2f : 0.4f), X - 6.f * S, RowY - 4.f * S, ListW, RowH - 4.f * S);
1225			}
1226			AddMenuHit(EMenuHitKind::SpellSlot, X - 6.f * S, RowY - 4.f * S, ListW, RowH - 4.f * S, i);
1227			FString Text;
1228			if (i < NumSlots)
1229			{
1230				const FName SpellId = Spellbook->GetSlotSpell(i);
1231				Text = FString::Printf(TEXT("[%s]  %s"), SlotKey(i), SpellId == NAME_None ? TEXT("(empty)") : *GBHudText::SpellName(this, SpellId));
1232			}
1233			else
1234			{
1235				const EGBElement Element = Spellbook->GetEnchantElement();
1236				Text = FString::Printf(TEXT("[T]  Weapon enchant: %s"), *GBHudText::ElementName(Element));
1237				DrawRect(GBHudText::ElementColor(Element), X - 6.f * S, RowY - 4.f * S, 4.f * S, RowH - 4.f * S);
1238			}
1239			DrawLabel(Text, Style.Text, X, RowY, 20.f, 0.f, bShadow);
1240		}
1241	
1242		// Known passives (always active, never equipped).
1243		FString Passives;
1244		if (Data)
1245		{
1246			for (const FName& SpellId : Spellbook->GetKnownSpells())
1247			{
1248				const FGBSpellDefinition* Def = Data->FindSpell(SpellId);
1249				if (Def && Def->bPassive)
1250				{
1251					Passives += (Passives.IsEmpty() ? TEXT("") : TEXT(", ")) + GBHudText::SpellName(this, SpellId);
1252				}
1253			}
1254		}
1255		const float PassY = ListY + (NumSlots + 1) * RowH + 20.f * S;
1256		DrawLabel(TEXT("Passives (always active)"), Style.Text, X, PassY, 18.f, 0.f, bShadow);
1257		DrawWrapped(Passives.IsEmpty() ? FString(TEXT("None yet")) : Passives, Style.Text, X, PassY + 28.f * S, ListW, 16.f, bShadow);
1258	
1259		// Right side: the spell chooser, or details of the selected slot.
1260		const float DX = X + ListW + 30.f * S;
1261		const float DW = W - ListW - 30.f * S;
1262		float DY = Y;
1263		if (MenuState.bChoosingSpell)
1264		{
1265			const TArray<FName> Options = GetAssignableSpells(Player);
1266			MenuState.SubCursor = FMath::Clamp(MenuState.SubCursor, 0, FMath::Max(0, Options.Num() - 1));
1267			DrawLabel(FString::Printf(TEXT("Spell for slot [%s]"), SlotKey(MenuState.Cursor)), Style.Text, DX, DY, 22.f, 0.f, bShadow, true);
1268			DY += 44.f * S;
1269			const float OptH = 32.f * S;
1270			const int32 Visible = FMath::Max(1, FMath::FloorToInt((H - 140.f * S) / OptH));
1271			const int32 First = FMath::Clamp(MenuState.SubCursor - Visible + 1, 0, FMath::Max(0, Options.Num() - Visible));
1272			for (int32 i = First; i < Options.Num() && i < First + Visible; ++i)
1273			{
1274				const FName SpellId = Options[i];
1275				if (i == MenuState.SubCursor)
1276				{
1277					DrawRect(Style.Accent * FLinearColor(1.f, 1.f, 1.f, 0.4f), DX - 6.f * S, DY - 3.f * S, DW * 0.8f, OptH - 2.f * S);
1278				}
