	const float Alpha = Era ? FMath::Clamp(Era->GetFadeAlpha(), 0.f, 1.f) : 0.f;
	if (Alpha <= 0.f)
	{
		return;
	}
	FillRect(0.f, 0.f, Canvas->ClipX, Canvas->ClipY, FLinearColor(0.82f, 0.9f, 1.f, Alpha));
}

