function validate() {
  let ok = true;
  for (const [id, [pal, rows]] of Object.entries(icons)) {
    if (rows.length !== 16) { console.log(`${id}: ${rows.length} rows`); ok = false; }
    rows.forEach((r, i) => {
      if (r.length !== 16) { console.log(`${id} row ${i}: length ${r.length} "${r}"`); ok = false; }
      for (const c of r) if (c !== '.' && !pal[c]) { console.log(`${id} row ${i}: unknown '${c}'`); ok = false; }
    });
  }
  return ok;
}

function crc32(buf) {
  let c, crc = 0xffffffff;
  for (let n = 0; n < buf.length; n++) {
    c = (crc ^ buf[n]) & 0xff;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    crc = (crc >>> 8) ^ c;
  }
  return (crc ^ 0xffffffff) >>> 0;
}
function png(w, h, rgba) {
  const chunk = (type, data) => {
    const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
    const td = Buffer.concat([Buffer.from(type), data]);
    const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(td));
    return Buffer.concat([len, td, crc]);
  };
  const ihdr = Buffer.alloc(13);
  ihdr.writeUInt32BE(w, 0); ihdr.writeUInt32BE(h, 4); ihdr[8] = 8; ihdr[9] = 6; ihdr[10] = 0; ihdr[11] = 0; ihdr[12] = 0;
  const raw = Buffer.alloc((w * 4 + 1) * h);
  for (let y = 0; y < h; y++) { raw[y * (w * 4 + 1)] = 0; rgba.copy(raw, y * (w * 4 + 1) + 1, y * w * 4, (y + 1) * w * 4); }
  return Buffer.concat([Buffer.from([137, 80, 78, 71, 13, 10, 26, 10]), chunk('IHDR', ihdr), chunk('IDAT', zlib.deflateSync(raw)), chunk('IEND', Buffer.alloc(0))]);
}

function preview(out) {
  const S = 8, pad = 4, ids = Object.keys(icons), cols = 5;
  const cw = (16 + pad * 2) * S, rowsN = Math.ceil(ids.length / cols);
  const W = cw * cols, H = cw * rowsN;
  const buf = Buffer.alloc(W * H * 4);
  for (let i = 0; i < W * H; i++) { buf[i * 4] = 0x1d; buf[i * 4 + 1] = 0x1d; buf[i * 4 + 2] = 0x25; buf[i * 4 + 3] = 255; }
  ids.forEach((id, n) => {
    const [pal, rows] = icons[id];
    const ox = (n % cols) * cw + pad * S, oy = Math.floor(n / cols) * cw + pad * S;
    rows.forEach((r, y) => [...r].forEach((c, x) => {
      if (c === '.') return;
      const hex = pal[c]; const R = parseInt(hex.slice(1, 3), 16), G = parseInt(hex.slice(3, 5), 16), B = parseInt(hex.slice(5, 7), 16);
      for (let dy = 0; dy < S; dy++) for (let dx = 0; dx < S; dx++) {
        const p = ((oy + y * S + dy) * W + ox + x * S + dx) * 4; buf[p] = R; buf[p + 1] = G; buf[p + 2] = B; buf[p + 3] = 255;
      }
    }));
  });
  fs.writeFileSync(out, png(W, H, buf));
  console.log('preview', out, ids.join(', '));
}

function insert(file) {
  let text = fs.readFileSync(file, 'utf8');
  const blocks = Object.entries(icons).map(([id, [pal, rows]]) => {
    const used = Object.keys(pal).filter(k => rows.some(r => r.includes(k)));
    const palText = used.map(k => `\t\t\t\t"${k}": "${pal[k]}"`).join(',\n');
    const rowText = rows.map(r => `\t\t\t\t"${r}"`).join(',\n');
    return `\t\t{\n\t\t\t"Id": "${id}",\n\t\t\t"Palette": {\n${palText}\n\t\t\t},\n\t\t\t"Rows": [\n${rowText}\n\t\t\t]\n\t\t}`;
  });
  // Drop earlier copies of these icons, then append before the closing bracket of "Sprites".
  for (const id of Object.keys(icons)) {
    const re = new RegExp(`,\\n\\t\\t\\{\\n\\t\\t\\t"Id": "${id}",[\\s\\S]*?\\n\\t\\t\\}(?=,\\n\\t\\t\\{|\\n\\t\\])`);
    text = text.replace(re, '');
  }
  const end = text.lastIndexOf('\n\t]\n}');
  if (end < 0) throw new Error('end of Sprites not found');
  text = text.slice(0, end) + ',\n' + blocks.join(',\n') + text.slice(end);
  JSON.parse(text);
  fs.writeFileSync(file, text);
  console.log('inserted', Object.keys(icons).length, 'icons into', file);
}

