// Replaces icon blocks in icons.js (one-off edit helper).
const fs = require('fs');
let src = fs.readFileSync('icons.js', 'utf8');
function rep(id, rowsArr, palName) {
  const start = src.indexOf(`  ${id}: [`);
  if (start < 0) throw new Error('no ' + id);
  const end = src.indexOf(']],\n', start) + 4;
  const body = `  ${id}: [${palName}, [\n` + rowsArr.map(r => `    '${r}',`).join('\n') + `]],\n`;
  src = src.slice(0, start) + body + src.slice(end);
}
const pad = (a) => { while (a.length < 16) a.push('................'); return a; };
rep('icon_fireball', pad(['................', '..........oooo..', '........ooyyyyo.', '.......oyywwwyyo', '....o.oayywwwwyo', '...oaoaayywwwyyo', '..oafaaaayywyyao', '.oaffraaaayyyaao', '.ofrrffaaaaaaao.', 'ofrdorffaaaaao..', 'odo.ofrffaaoo...', 'oo..ofrrffo.....', '...ofrdoo.......', '..ofdo..........', '..oo............']), 'FIRE');
rep('icon_flamethrower', pad(['................', '.............o..', '.........o..oyo.', '......o.oyooyyo.', '....ooaoayyayywo', '..ooffaaayywwwyo', 'ooffrfaaayywwwyo', 'odrrffaaayyywwyo', 'ooffrfaaayywwyyo', '..ooffaaaayyyyao', '....ooaoaayaayo.', '......o.oaoayo..', '.........o..oo..']), 'FIRE');
const A = ['wiiittc', 'iitttcc', 'ttcccdd'], A2 = ['wiittc', 'itttcc', 'tcccdd'];
const B = [['wii', 'wiiittc', 'wi'], ['iit', 'iitttcc', 'it'], ['tcc', 'ttcccdd', 'tc']];
const O = 'oooooooooooooooo';
const wall = ['................', O];
for (let k = 0; k < 3; k++) wall.push('o' + A[k] + 'o' + A2[k] + 'o');
wall.push(O);
for (let k = 0; k < 3; k++) wall.push('o' + B[k][0] + 'o' + B[k][1] + 'o' + B[k][2] + 'o');
wall.push(O);
for (let k = 0; k < 3; k++) wall.push('o' + A[k] + 'o' + A2[k] + 'o');
wall.push(O);
rep('icon_icewall', pad(wall), 'ICE');
const rune = [];
const bolt = ['.....oo.', '....oyo.', '...oywo.', '..oywwyo', '.oooywo.', '...oyo..', '...oo...'];
for (let y = 0; y < 16; y++) {
  let r = '';
  for (let x = 0; x < 16; x++) {
    const d = Math.hypot(x - 7.5, y - 7.5);
    let c = '.';
    if (d >= 5.5 && d <= 6.6) c = 'g'; else if ((d >= 4.8 && d < 5.5) || (d > 6.6 && d <= 7.4)) c = 'o';
    if (d >= 5.6 && d <= 6.4 && (x + y) % 5 === 0) c = 'y';
    r += c;
  }
  rune.push(r);
}
for (let y = 0; y < bolt.length; y++) {
  const row = rune[4 + y].split('');
  for (let x = 0; x < 8; x++) if (bolt[y][x] !== '.') row[4 + x] = bolt[y][x];
  rune[4 + y] = row.join('');
}
rep('icon_lightningrune', rune, 'BOLT');
rep('icon_weaponenchant', pad(['................', '......oo........', '.....omlo...l...', '....omlwlo.lwl..', '....ommllo..l...', '....odmmmo......', '...oooooooo.....', '...oywyyybo.....', '...oywyyybo.....', '...oywyybno..l..', '...oywyybno.lwl.', '...oyyybbno..l..', '...oonnnnoo.....', '...obbbbbbo.....', '....oooooo......']), 'ARC2');
if (!src.includes('const ARC2')) {
  src = src.replace('const ARC = {', "const ARC2 = { o: '#000000', d: '#441974', m: '#8548C0', l: '#C0A2E1', w: '#FFFFFF', y: '#FFE45A', b: '#C88A08', n: '#5A3A08' };\nconst ARC = {");
}
fs.writeFileSync('icons.js', src);
