function edit(f, pairs) {
  let s = fs.readFileSync(f, 'utf8');
  for (const [a, b] of pairs) {
    if (!s.includes(a)) { console.log('MISSING in', f, ':', a.slice(0, 100)); continue; }
    s = s.split(a).join(b);
  }
  fs.writeFileSync(f, s);
}
const T = (n) => '\t'.repeat(n);

// Cyber weapon block
{
  let s = fs.readFileSync('GBHUD_Cyber.cpp', 'utf8');
  const a = s.indexOf('void AGBHUD::DrawCyberWeapon');
  const b = s.indexOf('float AGBHUD::DrawCyberEffects');
  if (a > 0 && b > a) {
    s = s.slice(0, a) + fs.readFileSync(S + 'cyweapon.cpp.part', 'utf8') + s.slice(b);
    fs.writeFileSync('GBHUD_Cyber.cpp', s);
  } else console.log('weapon block not found');
}

