// Stages "HEAD + only the HUD rework's changes" for files another chat is also editing, without touching the
// working tree (its uncommitted work stays where it is). Run from the repo root.
const { execSync } = require('child_process');
const fs = require('fs');
const SCR = 'C:/Users/VNasher/AppData/Local/Temp/claude/c1b810ae341cf89c/6c499171-af23-4e77-afe4-86028ce8f216/scratchpad/';
const sh = (c, input) => execSync(c, { input, encoding: 'utf8', maxBuffer: 64 << 20 });
const head = (p) => sh(`git show HEAD:${p}`).replace(/\r\n/g, '\n');
function stage(p, text) {
  const sha = sh(`git hash-object -w --stdin`, text).trim();
  sh(`git update-index --cacheinfo 100644,${sha},${p}`);
  console.log('staged', p, sha.slice(0, 8));
}
function must(s, a) { if (!s.includes(a)) throw new Error('not found in HEAD: ' + a.slice(0, 80)); }

// GDD: changelog line, status, section 13.
stage('Design/GDD.md', require(SCR + 'gdd_hud.js')(head('Design/GDD.md')));

// Build.cs: RenderCore (GWhiteTexture for canvas triangles).
{
  let s = head('Glyphbound/Source/Glyphbound/Glyphbound.Build.cs');
  must(s, '"Slate", "SlateCore", "UMG"');
  s = s.replace('"Slate", "SlateCore", "UMG"', '"Slate", "SlateCore", "UMG", "RenderCore"');
  stage('Glyphbound/Source/Glyphbound/Glyphbound.Build.cs', s);
}

// GBDevCommands.cpp: the HUD include and the UI smoke block in place of the old quit step.
{
  const p = 'Glyphbound/Source/Glyphbound/Core/GBDevCommands.cpp';
  let s = head(p);
  const quit = '\t\tAdd(69.4f + S, TEXT("quit"), [](UWorld*, AGBPlayerCharacter*)';
  must(s, quit);
  must(s, '#include "World/GBTestArena.h"');
  const block = fs.readFileSync(SCR + 'ui_steps.cpp.part', 'utf8').replace(/\r\n/g, '\n').replace(/\n$/, '');
  s = s.replace(quit, block);
  s = s.replace('#include "World/GBTestArena.h"', '#include "World/GBTestArena.h"\n#include "UI/GBHUD.h"');
  // Sanity: the working copy must contain the same block (the one that was built and run).
  const work = fs.readFileSync(p, 'utf8').replace(/\r\n/g, '\n');
  if (!work.includes(block)) throw new Error('the UI block in the working copy differs from ui_steps.cpp.part');
  stage(p, s);
}

